#!/usr/bin/env sh
# Dependency-free Conventional Commits check, used by .githooks/commit-msg.
# Mirrors the main blaze-cache repo's commitlint policy (including the `bench` type).
set -eu

file="$1"
subject=$(head -n 1 "$file")

# Merge commits are generated by git and are exempt from the conventional prefix.
case "$subject" in
  Merge\ *|Revert\ *) exit 0 ;;
esac

TYPES='bench|build|chore|ci|docs|feat|fix|perf|refactor|revert|style|test'

if ! printf '%s\n' "$subject" | grep -Eq "^(${TYPES})(\([^()]+\))?!?: .+"; then
  echo "commit message must be conventional, e.g. \"feat(bindings): add ABI export\"" >&2
  echo "allowed types: ${TYPES}" >&2
  exit 1
fi

length=$(printf '%s' "$subject" | wc -c | tr -d ' ')
if [ "$length" -gt 100 ]; then
  echo "commit subject is too long (${length} > 100 characters)" >&2
  exit 1
fi
